                    },
                    badge
                  )
                : null,
              h(RefImage, {
                key: "pic",
                src: p.imageUrls?.[0],
                n: refFromId(p.id),
                alt: p.name,
                className: "h-40 w-full rounded-2xl object-cover sm:h-44"
              })
            ].filter(Boolean)),
            h("div", { key: "title-row", className: "mt-3 flex items-start justify-between gap-2" }, [
              h("div", { key: "titles", className: "min-w-0" }, [
                h("h3", { key: "n", className: "truncate font-semibold text-slate-900 dark:text-white" }, p.name),
                h(
                  "p",
                  { key: "c", className: "text-xs text-slate-500 dark:text-slate-400" },
                  CATEGORY_LABELS[p.category] || p.category
                )
              ]),
              h(
                "button",
                {
                  key: "wish",
                  type: "button",
                  className: "tap-target rounded-xl p-2 text-slate-400 hover:bg-white/10 hover:text-rose-400",
                  "aria-label": "Wishlist"
                },
                h(Heart, { className: "h-5 w-5" })
              )
            ]),
            h("div", { key: "price-row", className: "mt-2 flex items-center justify-between" }, [
              h("span", { key: "pr", className: "text-lg font-bold text-sky-600 dark:text-sky-300" }, formatGhc(p.price)),
              h("span", { key: "st", className: "text-xs text-slate-500 dark:text-slate-400" }, `${p.stock ?? 0} in stock`)
            ]),
            formatSellerPaymentSnippet(p.sellerPayment) &&
              h(
                "p",
                {
                  key: "pay-snippet",
                  className: "mt-2 line-clamp-2 text-[11px] leading-snug text-slate-500 dark:text-slate-400"
                },
                formatSellerPaymentSnippet(p.sellerPayment)
              ),
            h(
              Button,
              {
                key: "add",
                variant: "ghost",
                className: "mt-3 w-full !justify-center !rounded-2xl border-sky-500/30",
                type: "button",
                disabled: (p.stock ?? 0) <= 0,
                onClick: () => add(p, 1)
              },
              [
                h(ShoppingCart, { key: "ic", className: "h-4 w-4" }),
                h("span", { key: "tx" }, (p.stock ?? 0) <= 0 ? "Out of stock" : "Add to cart")
              ]
            )
          ]);
        })
      )
    ]),
    h(CartDrawer, { key: "cart", open: cartOpen, onClose: () => setCartOpen(false) }),
    h(
      "button",
      {
        key: "fab-cart",
        type: "button",
        className:
          "fixed bottom-4 right-4 z-30 flex items-center gap-2 rounded-full bg-gradient-to-r from-sky-500 to-blue-600 px-5 py-3 text-sm font-semibold text-white shadow-xl shadow-sky-900/40 sm:hidden",
        onClick: () => setCartOpen(true)
      },
      [h(ShoppingCart, { key: "i", className: "h-5 w-5" }), h("span", { key: "t" }, "Cart")]
    )
  ]);
}

export function ProfilePage() {
  const [cartOpen, setCartOpen] = useState(false);
  const { user, accessToken, setUser } = useAuth();
  const [displayName, setDisplayName] = useState("");
  const [email, setEmail] = useState("");
  const [phone, setPhone] = useState("");
  const [saveErr, setSaveErr] = useState("");
  const [saveOk, setSaveOk] = useState("");
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (!accessToken) {
      setDisplayName("");
      setEmail("");
      setPhone("");
      return;
    }
    let cancelled = false;
    apiFetch("/api/auth/me", { headers: { Authorization: `Bearer ${accessToken}` } })
      .then((meData) => {
        if (cancelled) return;
        if (meData?.user) {
          setDisplayName(meData.user.displayName || "");
          setEmail(meData.user.email || "");
          setPhone(meData.user.phone || "");
          setUser(meData.user);
        }
      })
      .catch(() => {});
    return () => {
      cancelled = true;
    };
  }, [accessToken]);

  const saveProfile = async () => {
    setSaveErr("");
    setSaveOk("");
    if (!accessToken) return;
    setSaving(true);
    try {
      const data = await apiFetch("/api/auth/profile", {
        method: "PATCH",
        headers: { Authorization: `Bearer ${accessToken}` },
        json: { displayName: displayName.trim(), phone: phone.trim() }
      });
      if (data.user) setUser(data.user);
      setSaveOk("Profile updated.");
    } catch (ex) {
      setSaveErr(ex.message || "Save failed");
    } finally {
      setSaving(false);
    }
  };

  return h("div", { className: "min-h-screen" }, [
    h(BuyerHeader, { onOpenCart: () => setCartOpen(true), hideSearch: true }),
    h("div", { className: "mx-auto max-w-3xl px-4 py-10 sm:px-6" }, [
      h("div", { className: "mb-8 flex flex-col items-center text-center" }, [
        h(RefImage, { key: "avatar", n: 12, alt: "Profile", className: "h-24 w-24 rounded-full object-cover ring-4 ring-sky-500/30" }),
        h(
          "h1",
          { key: "title", className: "mt-4 font-display text-2xl font-bold text-slate-900 dark:text-white" },
          displayName || user?.displayName || user?.email || "Your profile"
        ),
        h("p", { key: "sub", className: "text-sm text-slate-500 dark:text-slate-400" }, user?.email || "Sign in to sync your account")
      ]),
      h(GlassPanel, { className: "mb-6" }, [
        h("h2", { className: "text-lg font-semibold text-slate-900 dark:text-white" }, "Account details"),
        h("div", { className: "mt-4 space-y-4" }, [
          h(Field, { key: "f-name", label: "Display name" }, h(TextInput, { value: displayName, onChange: (e) => setDisplayName(e.target.value), placeholder: "Your name" })),
          h(Field, { key: "f-email", label: "Email" }, h(TextInput, { type: "email", value: email, disabled: true })),
          h(Field, { key: "f-phone", label: "Phone" }, h(TextInput, { value: phone, onChange: (e) => setPhone(e.target.value), placeholder: "+1 …" })),
          saveErr && h("p", { key: "save-err", className: "text-sm text-rose-400" }, saveErr),
          saveOk && h("p", { key: "save-ok", className: "text-sm text-emerald-400" }, saveOk),
          h(
            Button,
            {
              key: "save-btn",
              variant: "primary",
              className: "w-full sm:w-auto",
              type: "button",
              onClick: saveProfile,
              loading: saving,
              disabled: !accessToken
            },
            "Save changes"
          ),
          !accessToken &&
            h("p", { key: "guest-note", className: "text-sm text-amber-400" }, "You are browsing as a guest. Log in to persist profile changes.")
        ])
      ])
    ]),
    h(CartDrawer, { open: cartOpen, onClose: () => setCartOpen(false) })
  ]);
}

